import itertools
sheet = 'W1::Allowed assignments'
rows = data_rows(sheet, {'L': 'string', 'M': 'string', 'N': 'number'}, start_row=812, end_row=820)
tasks = list(set(label(sheet, f'L{r}') for r in rows))
workers = list(set(label(sheet, f'M{r}') for r in rows))
cost_map = {(label(sheet, f'L{r}'), label(sheet, f'M{r}')): num(sheet, f'N{r}') for r in rows}
max_covered = 0
for r in range(1, len(tasks) + 1):
    for p in itertools.permutations(workers, r):
        possible = True
        for i, t in enumerate(tasks[:r]):
            if (t, p[i]) not in cost_map:
                possible = False
                break
        if possible:
            max_covered = max(max_covered, r)
result = max_covered

